    "description": "<div class=\"product-description-content\" style=\"font-family: inherit; color: #334155; line-height: 1.8;\">\n  <h3 style=\"font-size: 1.2rem; font-weight: 800; color: #0f172a; margin-bottom: 0.75rem;\">\n    Thông Tin Chi Tiết - Cá Ali Thái - Freiberg'S Peacock Cichlid\n  </h3>\n  <p style=\"margin-bottom: 1rem;\">\n    ✨ <strong>Cá Ali Thái - Freiberg'S Peacock Cichlid</strong> thuộc nhóm <strong>Cá Ali Thái (Cichlid)</strong>, được tuyển chọn và thuần dưỡng kỹ lưỡng phù hợp nguồn nước tại <strong>Đà Nẵng</strong>. Cá khỏe mạnh, bơi lội linh hoạt, màu sắc tươi đẹp và ăn khỏe.\n  </p>\n  <h4 style=\"font-size: 1.05rem; font-weight: 700; color: #1e293b; margin-top: 1.25rem; margin-bottom: 0.5rem;\">\n    💧 Điều Kiện Môi Trường Sống Lý Tưởng:\n  </h4>\n  <ul style=\"padding-left: 1.25rem; margin-bottom: 1.25rem; line-height: 1.9;\">\n    <li><strong>Độ pH phù hợp:</strong> 7.5 - 8.5</li>\n    <li><strong>Nhiệt độ nước:</strong> 25 - 28°C</li>\n    <li><strong>Thức ăn ưa thích:</strong> Cám viên chìm/nổi cho Cichlid, tép băm</li>\n    <li><strong>Tập tính sinh thái:</strong> Năng động, thích hồ đá & lũa, màu sắc rực rỡ</li>\n  </ul>\n  <h4 style=\"font-size: 1.05rem; font-weight: 700; color: #1e293b; margin-top: 1.25rem; margin-bottom: 0.5rem;\">\n    🌟 Đặc Điểm Nổi Bật:\n  </h4>\n  <p style=\"margin-bottom: 1.25rem;\">\n    Dòng cá này mang sắc màu rực rỡ khỏe khoắn, rất thích hợp cho các hồ đá, hồ thủy sinh bố cục hoặc hồ phong thủy tại Đà Nẵng.\n  </p>\n  <h4 style=\"font-size: 1.05rem; font-weight: 700; color: #1e293b; margin-top: 1.25rem; margin-bottom: 0.5rem;\">\n    🛡️ Cam Kết Chất Lượng & Giao Hàng Từ AquaCraft Đà Nẵng:\n  </h4>\n  <ul style=\"padding-left: 1.25rem; margin-bottom: 0; line-height: 1.9;\">\n    <li>Cá được cách ly, dưỡng khỏe 100% trước khi xuất bán.</li>\n    <li><strong>Bảo hành cá sống 100%:</strong> Quay video khui thùng khi nhận hàng để được bù mới hoặc hoàn tiền nếu có rủi ro vận chuyển.</li>\n    <li><strong>Nội thành Đà Nẵng:</strong> Giao hỏa tốc trong 1 - 2 giờ tại Hải Châu, Thanh Khê, Sơn Trà, Ngũ Hành Sơn, Cẩm Lệ, Liên Chiểu.</li>\n    <li><strong>Toàn quốc:</strong> Đóng túi oxy 3 lớp thùng xốp giữ nhiệt, vận chuyển an toàn 24 - 48h.</li>\n  </ul>\n</div>"
